<?php namespace App\Console\Commands; use App\Models\Central\Tenant;use App\Services\Tenancy\TenantProvisioner;use Illuminate\Console\Command;use Throwable; class TenantProvisionCommand extends Command {protected $signature='tenant:provision {tenant : Central tenant ID}';protected $description='Provision one explicit tenant safely.';public function handle(TenantProvisioner $p):int{try{$p->provision(Tenant::query()->findOrFail($this->argument('tenant')));$this->info('Tenant provisioning completed.');return self::SUCCESS;}catch(Throwable $e){$this->error('Tenant provisioning failed: '.mb_substr($e->getMessage(),0,300));return self::FAILURE;}}}
